try:
    import numpy as np

    df['month'] = pd.to_datetime(df['month'])
    df_valid = df[df['row_kind'].isin(['counted', 'netted'])] if 'row_kind' in df.columns else df.copy()

    monthly_mrr = (
        df_valid.sort_values('month')
        .groupby(['month', 'account_id'])['mrr']
        .last()
        .reset_index()
        .groupby('month')['mrr']
        .sum()
        .reset_index()
        .sort_values('month')
    )

    if len(monthly_mrr) >= 2:
        last_month_mrr = monthly_mrr.iloc[-1]['mrr']
        prev_month_mrr = monthly_mrr.iloc[-2]['mrr']
        last_month_label = monthly_mrr.iloc[-1]['month'].strftime('%Y-%m')
        prev_month_label = monthly_mrr.iloc[-2]['month'].strftime('%Y-%m')

        pct_change = ((last_month_mrr - prev_month_mrr) / prev_month_mrr) * 100 if prev_month_mrr != 0 else 0.0
        direction = 'up' if pct_change > 0.5 else ('down' if pct_change < -0.5 else 'flat')

        result['trends'].append({
            "column": "mrr",
            "period": "MoM",
            "direction": direction,
            "pct_change": round(pct_change, 4),
            "segment": None
        })

    if 'plan' in df_valid.columns and len(monthly_mrr) >= 2:
        last_month = monthly_mrr.iloc[-1]['month']
        prev_month = monthly_mrr.iloc[-2]['month']

        for plan_val in df_valid['plan'].dropna().unique():
            seg = df_valid[df_valid['plan'] == plan_val]
            def last_mrr_for_month(m):
                sub = seg[seg['month'] == m]
                if sub.empty:
                    return 0.0
                return sub.sort_values('month').groupby('account_id')['mrr'].last().sum()

            last_val = last_mrr_for_month(last_month)
            prev_val = last_mrr_for_month(prev_month)
            if prev_val != 0:
                seg_pct = ((last_val - prev_val) / prev_val) * 100
            else:
                seg_pct = 0.0
            seg_dir = 'up' if seg_pct > 0.5 else ('down' if seg_pct < -0.5 else 'flat')
            result['trends'].append({
                "column": "mrr",
                "period": "MoM",
                "direction": seg_dir,
                "pct_change": round(seg_pct, 4),
                "segment": str(plan_val)
            })

    result['assumptions'].append(
        "MRR per month = sum of each account_id's last mrr value in that month; row_kind filtered to counted/netted."
    )
    result['assumptions'].append(
        f"Last month is {last_month_label}, previous month is {prev_month_label}."
    )

except Exception as e:
    result['trends'].append({
        "column": "mrr",
        "period": "MoM",
        "direction": "flat",
        "pct_change": 0.0,
        "segment": None
    })
    result['assumptions'].append(f"Trend computation error: {str(e)[:120]}")

